-- শুধু SELECT, কিছু বদলায় না -- কোচবিহার নন-বিলড ব্যাচের patientId সিরিয়াল যাচাই
select
  substring("patientId" from 5 for 8) as date_part,
  max(substring("patientId" from 14)::int) as max_serial_used
from public.patients
where "patientId" ~ '^COB-\d{8}-\d+$'
  and substring("patientId" from 5 for 8) in ('14022025', '15022025', '17022025', '28022025', '03032025', '07032025', '17032025', '18032025', '21032025', '28032025', '04042025', '05042025', '09042025', '11042025', '14042025', '18042025', '25042025', '28042025', '02052025', '05052025', '09052025', '12052025', '16052025', '19052025', '23052025', '30052025', '01062025', '02062025', '06062025', '09062025', '12062025', '13062025', '16062025', '20062025', '23062025', '30062025', '04072025', '05072025', '11072025', '12072025', '18072025', '21072025', '22072025', '01082025', '04082025', '07082025', '08082025', '09082025', '11082025', '15082025', '18082025', '22082025', '25082025', '29082025', '05092025', '08092025', '12092025', '15092025', '19092025', '03102025', '07102025', '11102025', '17102025', '20102025', '21102025', '24102025', '27102025', '03112025', '07112025', '17112025', '21112025', '26112025', '28112025', '29112025', '01122025', '05122025', '12122025', '15122025', '22122025', '29122025')
group by date_part
order by date_part;
